// Record-based cases 3 and 5, claim side (detect, not verify - 2026-10-14).
//   Case 3: the customer says a refund is missing OR its amount is wrong.
//           Straight to manual when record_case3_enforce is on (Tseko, 2026-10-15).
//   Case 5: the customer says they cancelled before the renewal. Only TAGGED
//           here (claim_cancelled_before_renewal). The refund requests flow
//           diverts it at the rejection macro, and only there (2026-10-15).
// Never throws: an unreadable AI answer counts as "no claim".
const input = $('When Executed by Another Workflow').first().json;
const cfg = $('Get Project Config').first().json || {};
function truthy(v) {
  return v === true || v === 1 || v === 'true' || v === '1' || v === 'yes';
}
const c3Enabled = truthy(cfg.record_case3_enabled);
const c3Enforce = truthy(cfg.record_case3_enforce);
const c5Enabled = truthy(cfg.record_case5_enabled);

let ai = {};
let aiError = null;
try {
  const raw = $('Detect claims').first().json || {};
  if (raw.error) throw new Error(typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error).slice(0, 200));
  let t = raw.output && raw.output[0] && raw.output[0].content && raw.output[0].content[0] && raw.output[0].content[0].text;
  if (typeof t === 'string') t = JSON.parse(t);
  ai = t || {};
} catch (e) {
  ai = {};
  aiError = String(e && e.message || e);
}

const refundMissing = ai.refund_missing === true;
const refundAmount = ai.refund_amount_disputed === true;
const cancelledBefore = ai.cancelled_before_renewal === true;

const case3 = c3Enabled && (refundMissing || refundAmount);
const case5Claim = c5Enabled && cancelledBefore;

const tags = [];
if (case3) {
  if (refundMissing) tags.push('claim_refund_missing');
  if (refundAmount) tags.push('claim_refund_amount');
  tags.push('record_case_3', 'record_based_flag');
}
if (case5Claim) tags.push('claim_cancelled_before_renewal');

function clip(s) { return String(s || '').replace(/\s+/g, ' ').trim().slice(0, 200); }

return [{
  json: {
    claims_checked: true,
    stage: input.stage || null,
    ticket_id: input.ticket_id,
    case3: case3,
    case5_claim: case5Claim,
    should_block: case3 && c3Enforce,
    case3_enforce: c3Enforce,
    claim_refund_missing: refundMissing,
    claim_refund_amount: refundAmount,
    claim_cancelled_before_renewal: cancelledBefore,
    evidence_refund_missing: clip(ai.evidence_refund_missing),
    evidence_refund_amount: clip(ai.evidence_refund_amount_disputed),
    evidence_cancelled_before_renewal: clip(ai.evidence_cancelled_before_renewal),
    tags: tags,
    ai_error: aiError
  },
  pairedItem: { item: 0 }
}];

// Internal note for a case 3 divert. The payments data only enriches the
// note; the divert itself was already decided by the claim (detect-only).
const cfg = $('Get Project Config').first().json || {};
const v = $('Evaluate claims').first().json;
let resp = {};
try { resp = $('bot/search').first().json || {}; } catch (e) { resp = {}; }
const body = resp.body || {};

function day(iso) { return iso ? String(iso).slice(0, 10) : '?'; }

const lines = [
  'Note: This ticket matched record-based case 3 - the customer says a refund is missing or that its amount is wrong.',
  '',
  'Automation has been stopped and no reply was sent to the customer. Please handle this ticket manually.',
  ''
];
if (v.claim_refund_missing) lines.push('Customer says the refund is missing: "' + v.evidence_refund_missing + '"');
if (v.claim_refund_amount) lines.push('Customer says the refund amount is wrong: "' + v.evidence_refund_amount + '"');
lines.push('');

if (resp.statusCode === 200) {
  const refunds = Array.isArray(body.refundedTransactions) ? body.refundedTransactions : [];
  if (refunds.length === 0) {
    lines.push('Refunds on record: none for the email the customer wrote from.');
  } else {
    lines.push('Refunds on record (' + refunds.length + '):');
    refunds.forEach(function (r) {
      const amount = (r.amount != null ? r.amount : '?') + (r.currency ? ' ' + r.currency : '');
      const provider = r.provider && r.provider.type ? r.provider.type : 'unknown provider';
      const refundDate = r.refundDate ? day(r.refundDate) : 'not available yet';
      lines.push('- ' + amount + ' refunded, ' + (r.type || 'unknown type') + ' charge of ' + day(r.transactionDate) + ', refund date ' + refundDate + ', ' + provider);
    });
  }
  if (body.subscriptionStatus) lines.push('Subscription status: ' + body.subscriptionStatus + (body.cancellationDate ? ', cancellation date ' + day(body.cancellationDate) : ''));
} else {
  lines.push('Payments lookup: no account found for the email the customer wrote from' + (resp.statusCode ? ' (status ' + resp.statusCode + ')' : '') + '.');
}

const ticket = { comment: { public: false, body: lines.join('\n') } };
const openStatusId = Number(cfg.ticket_custom_status_open_id);
if (Number.isFinite(openStatusId) && openStatusId > 0) ticket.custom_status_id = openStatusId;
const allowFieldId = Number(cfg.ticket_field_allow_automation);
if (Number.isFinite(allowFieldId) && allowFieldId > 0) ticket.custom_fields = [{ id: allowFieldId, value: '_no_' }];

return [{ json: { ticket_id: v.ticket_id, zendesk_body: { ticket: ticket } }, pairedItem: { item: 0 } }];

// Single exit point, so the caller always gets the same shape back.
// should_block is only true when the ticket was actually taken out of
// automation. If that Zendesk write failed, the caller carries on as before.
let v = null;
try { v = $('Evaluate claims').first().json; } catch (e) { v = null; }
if (!v) {
  v = { claims_checked: false, case3: false, case5_claim: false, should_block: false, tags: [] };
}
let blocked = false;
if (v.should_block) {
  try {
    const r = $('Take out of automation').first().json || {};
    blocked = !r.error;
  } catch (e) { blocked = false; }
}
const out = Object.assign({}, v, { should_block: blocked, block_requested: !!v.should_block });
return [{ json: out, pairedItem: { item: 0 } }];
